INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Elena had been leading a struggling sales team for six months. Instead of assigning blame, she organized weekly coaching sessions focused on practical skills. Slowly, team performance began to improve. By the end of the quarter, the team had exceeded its sales target for the first time in over a year."}'::jsonb, '{"key_points": ["Elena led a struggling sales team", "she organized weekly coaching sessions", "performance slowly improved", "the team exceeded its target by quarter end"]}'::jsonb, 52, 0.55, 'B2', 'approved', 'exam', 'business', 'd1000000-0000-4000-8000-000000000012', 1),
('passage_reconstruction', '{"passage": "A manufacturing plant experienced a sudden equipment failure during peak production. The maintenance team worked through the night to diagnose the problem. They discovered a worn component that had gone unnoticed during routine inspections. After replacing the part, production resumed the next morning with only minor delays."}'::jsonb, '{"key_points": ["a plant had a sudden equipment failure", "the maintenance team worked through the night", "they found a worn, unnoticed component", "production resumed the next morning"]}'::jsonb, 48, 0.58, 'B2', 'approved', 'exam', 'business', 'd1000000-0000-4000-8000-000000000012', 2),
('passage_reconstruction', '{"passage": "Thank you for your patience during the recent system migration. We understand that the temporary downtime affected your team''s workflow, and we sincerely apologize for any disruption caused. All services have now been fully restored, and we have implemented additional safeguards to prevent similar issues going forward."}'::jsonb, '{"key_points": ["thanks for patience during the migration", "apologizes for the downtime and disruption", "services are fully restored", "additional safeguards have been implemented"]}'::jsonb, 48, 0.56, 'B2', 'approved', 'exam', 'business', 'd1000000-0000-4000-8000-000000000012', 3);
