INSERT INTO items (item_type_id, content, answer_set, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('email_writing', '{"prompt": "Your company recently opened a new regional office. Your manager, Ms. Okafor, has asked for your ideas about how to help new hires there feel welcome. Write an email to her suggesting three ways to improve the new office''s onboarding experience. Your suggestions must come from the following three themes: welcome packages, buddy system, local team introductions. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'd1000000-0000-4000-8000-000000000014', 1),
('email_writing', '{"prompt": "Your department is launching a new internal newsletter. Your manager, Mr. Boyd, wants ideas for what content to include. Write an email to him suggesting three types of content for the newsletter. Your suggestions must come from the following three themes: employee spotlights, project updates, company announcements. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'd1000000-0000-4000-8000-000000000014', 2);
